// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/string.h>

/*
 * Lowercase as the kernel's tolower() defines it (lib/ctype.c): ASCII A-Z,
 * plus the Latin-1 uppercase range 0xc0-0xde except 0xd7 (multiplication sign).
 * Independent of the code under test.
 */
static int ref_lower(int c)
{
	if (c >= 'A' && c <= 'Z')
		return c + ('a' - 'A');
	if (c >= 0xc0 && c <= 0xde && c != 0xd7)
		return c + ('a' - 'A');
	return c;
}

static int sgn(int v)
{
	return (v > 0) - (v < 0);
}

static void strncasecmp_equal_same_case(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("hello", "hello", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "a", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "", 1), 0);
}

static void strncasecmp_equal_mixed_case(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("HeLLo", "hEllO", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ABC", "abc", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("Content-Type", "content-TYPE", 12), 0);
}

static void strncasecmp_ordering(struct kunit *test)
{
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abd", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abd", "abc", 3), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("ABC", "abd", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("ABD", "abc", 3), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("apple", "BANANA", 6), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("Banana", "apple", 6), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("zebra", "APPLE", 5), 0);
}

/* The return value is the difference of the case-folded characters. */
static void strncasecmp_exact_case_folded_difference(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "B", 1), -1);
	KUNIT_EXPECT_EQ(test, strncasecmp("B", "a", 1), 1);
	KUNIT_EXPECT_EQ(test, strncasecmp("Z", "a", 1), 25);
	KUNIT_EXPECT_EQ(test, strncasecmp("A", "z", 1), -25);
	KUNIT_EXPECT_EQ(test, strncasecmp("xA", "XB", 2), -1);
}

static void strncasecmp_zero_length(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "xyz", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ABC", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "a", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "", 0), 0);
}

static void strncasecmp_single_char_length(struct kunit *test)
{
	/* Only the first character is examined. */
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ABD", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "Abd", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "ZZZ", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("ZZZ", "abc", 1), 0);
}

/* Off-by-one checks: a mismatch at index len-1 counts, index len does not. */
static void strncasecmp_length_boundary(struct kunit *test)
{
	KUNIT_EXPECT_LT(test, strncasecmp("abcx", "ABCy", 4), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abcx", "ABCy", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("Bbc", "abc", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("aBC", "ABC", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("hello world", "HELLO there", 6), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("hello world", "HELLO there", 7), 0);
}

static void strncasecmp_nul_terminator(struct kunit *test)
{
	/* len beyond both strings stops at the NUL. */
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ABC", 10), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "", 10), 0);

	/* Shorter string ends first: it compares less or greater. */
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "ABCD", 4), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("ABCD", "abc", 4), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("ab", "abc", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abc", "ab", 3), 0);

	/* Extra characters past len are ignored. */
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ABCD", 3), 0);
}

static void strncasecmp_embedded_nul(struct kunit *test)
{
	/* The compare stops at the first NUL of either string. */
	KUNIT_EXPECT_EQ(test, strncasecmp("a\0b", "A\0c", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("a\0b", "A\0c", 2), 0);
}

static void strncasecmp_empty_strings(struct kunit *test)
{
	KUNIT_EXPECT_LT(test, strncasecmp("", "a", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("a", "", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("", "a", 5), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("a", "", 5), 0);
}

static void strncasecmp_ascii_letters_fold(struct kunit *test)
{
	char lower[2] = { 0, 0 };
	char upper[2] = { 0, 0 };
	int c;

	for (c = 'a'; c <= 'z'; c++) {
		lower[0] = (char)c;
		upper[0] = (char)(c - 'a' + 'A');
		KUNIT_EXPECT_EQ(test, strncasecmp(lower, upper, 1), 0);
		KUNIT_EXPECT_EQ(test, strncasecmp(upper, lower, 1), 0);
	}
}

/* Characters adjacent to the letter ranges must not be folded. */
static void strncasecmp_non_letters_not_folded(struct kunit *test)
{
	KUNIT_EXPECT_NE(test, strncasecmp("@", "`", 1), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("[", "{", 1), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("^", "~", 1), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("Z", "[", 1), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("0", "P", 1), 0);
}

/* Bytes are compared as unsigned char. */
static void strncasecmp_high_bytes_unsigned(struct kunit *test)
{
	KUNIT_EXPECT_GT(test, strncasecmp("\xff", "\x01", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("\x01", "\xff", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("\x80", "\x7f", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("\xff", "\xff", 1), 0);
	/* Latin-1 upper/lower pairs fold, per the kernel's ctype table. */
	KUNIT_EXPECT_EQ(test, strncasecmp("\xc1", "\xe1", 1), 0);
	/* 0xd7 (multiplication sign) has no case and must not fold. */
	KUNIT_EXPECT_NE(test, strncasecmp("\xd7", "\xf7", 1), 0);
}

static void strncasecmp_long_string_mismatch_position(struct kunit *test)
{
	/* Only the last character (index 35) differs: 'Z' vs 'y' folds to z > y. */
	const char *s = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
	const char *t = "0123456789abcdefghijklmnopqrstuvwxyy";

	KUNIT_EXPECT_EQ(test, strncasecmp(s, t, 35), 0);
	KUNIT_EXPECT_GT(test, strncasecmp(s, t, 36), 0);
	KUNIT_EXPECT_LT(test, strncasecmp(t, s, 36), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp(s, t, 100), sgn(strncasecmp(s, t, 36)));
}

/* Exhaustive: every non-NUL byte pair must match the ASCII-folded difference. */
static void strncasecmp_single_byte_exhaustive(struct kunit *test)
{
	char a[2] = { 0, 0 };
	char b[2] = { 0, 0 };
	int x, y, ret, expected;
	int failures = 0;
	int bad_x = 0, bad_y = 0, bad_ret = 0;

	for (x = 1; x < 256; x++) {
		for (y = 1; y < 256; y++) {
			a[0] = (char)x;
			b[0] = (char)y;
			ret = strncasecmp(a, b, 1);
			expected = ref_lower(x) - ref_lower(y);
			if (ret != expected) {
				if (!failures++) {
					bad_x = x;
					bad_y = y;
					bad_ret = ret;
				}
			}
		}
	}

	KUNIT_EXPECT_EQ_MSG(test, failures, 0,
			    "first bad pair %#x vs %#x returned %d",
			    bad_x, bad_y, bad_ret);
}

static void strncasecmp_symmetry(struct kunit *test)
{
	static const char * const strs[] = {
		"", "a", "A", "ab", "AB", "b", "abc", "ABD", "\xff",
	};
	size_t i, j;
	int len;

	for (i = 0; i < ARRAY_SIZE(strs); i++) {
		for (j = 0; j < ARRAY_SIZE(strs); j++) {
			for (len = 0; len <= 4; len++) {
				KUNIT_EXPECT_EQ(test,
						sgn(strncasecmp(strs[i], strs[j], len)),
						-sgn(strncasecmp(strs[j], strs[i], len)));
			}
		}
	}
}

static void strncasecmp_header_names(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("Content-Length: 5", "content-length", 14), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("Content-Length: 5", "content-length", 15), 0);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(strncasecmp_equal_same_case),
	KUNIT_CASE(strncasecmp_equal_mixed_case),
	KUNIT_CASE(strncasecmp_ordering),
	KUNIT_CASE(strncasecmp_exact_case_folded_difference),
	KUNIT_CASE(strncasecmp_zero_length),
	KUNIT_CASE(strncasecmp_single_char_length),
	KUNIT_CASE(strncasecmp_length_boundary),
	KUNIT_CASE(strncasecmp_nul_terminator),
	KUNIT_CASE(strncasecmp_embedded_nul),
	KUNIT_CASE(strncasecmp_empty_strings),
	KUNIT_CASE(strncasecmp_ascii_letters_fold),
	KUNIT_CASE(strncasecmp_non_letters_not_folded),
	KUNIT_CASE(strncasecmp_high_bytes_unsigned),
	KUNIT_CASE(strncasecmp_long_string_mismatch_position),
	KUNIT_CASE(strncasecmp_single_byte_exhaustive),
	KUNIT_CASE(strncasecmp_symmetry),
	KUNIT_CASE(strncasecmp_header_names),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

MODULE_DESCRIPTION("KUnit tests for strncasecmp");
MODULE_LICENSE("GPL");

// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/string.h>

/* Empty @s: nothing to scan, so the span is zero. */
static void agent_strcspn_empty_s(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("", "abc"), (size_t)0);
}

/* Empty @reject: no character can match, so the span is the whole string. */
static void agent_strcspn_empty_reject(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abc", ""), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("a", ""), (size_t)1);
}

/* Both empty: zero. */
static void agent_strcspn_both_empty(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("", ""), (size_t)0);
}

/* No overlap between @s and @reject: result equals strlen(@s). */
static void agent_strcspn_no_match(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello", "xyz"), (size_t)5);
	KUNIT_EXPECT_EQ(test, strcspn("hello", "HELO"), (size_t)5);
}

/* Match on the very first character: result is zero. */
static void agent_strcspn_match_first(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abc", "a"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("abc", "cba"), (size_t)0);
}

/* Match on the last character: result is strlen - 1. */
static void agent_strcspn_match_last(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abc", "c"), (size_t)2);
	KUNIT_EXPECT_EQ(test, strcspn("xyz!", "!"), (size_t)3);
}

/* Match in the middle: result is the index of the match. */
static void agent_strcspn_match_middle(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "d"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "b"), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "e"), (size_t)4);
}

/* Several characters from @reject occur in @s: the earliest one wins. */
static void agent_strcspn_earliest_match_wins(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcabc", "cb"), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn("hello world", "ow"), (size_t)4);
	KUNIT_EXPECT_EQ(test, strcspn("hello world", "dlh"), (size_t)0);
}

/* Duplicated characters in @reject must not change the result. */
static void agent_strcspn_duplicate_reject(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "eeeddd"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "zzzzz"), (size_t)6);
}

/* Repeated characters in @s: the scan stops at the first occurrence. */
static void agent_strcspn_repeated_s(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("aaaab", "b"), (size_t)4);
	KUNIT_EXPECT_EQ(test, strcspn("baaaa", "b"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("aaaa", "a"), (size_t)0);
}

/* Comparison is case-sensitive. */
static void agent_strcspn_case_sensitive(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcABC", "A"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn("abcABC", "a"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("ABCabc", "a"), (size_t)3);
}

/* A single-character @s is handled at both boundaries. */
static void agent_strcspn_single_char(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("x", "x"), (size_t)0);
	KUNIT_EXPECT_EQ(test, strcspn("x", "y"), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn("x", ""), (size_t)1);
}

/* Non-ASCII bytes must compare as plain byte values, including 0x80 and 0xff. */
static void agent_strcspn_high_bytes(struct kunit *test)
{
	static const char s[] = { 'a', (char)0x80, 'b', (char)0xff, 'c', 0 };

	KUNIT_EXPECT_EQ(test, strcspn(s, "\x80"), (size_t)1);
	KUNIT_EXPECT_EQ(test, strcspn(s, "\xff"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn(s, "\x7f\x81\xfe"), (size_t)5);
}

/*
 * For every non-NUL byte value v, a string with v at index 2 must report 2
 * when @reject contains only v, and 5 when @reject contains a different byte.
 */
static void agent_strcspn_all_byte_values(struct kunit *test)
{
	char s[6] = { 0 };
	char reject[2] = { 0, 0 };
	int v;

	for (v = 1; v < 256; v++) {
		/* Filler byte that differs from v; the other reject byte differs from v too. */
		char filler = (v == 'a') ? 'b' : 'a';
		char other = (v == 'z') ? 'w' : 'z';

		s[0] = filler;
		s[1] = filler;
		s[2] = (char)v;
		s[3] = filler;
		s[4] = filler;
		s[5] = '\0';

		reject[0] = (char)v;
		KUNIT_ASSERT_EQ_MSG(test, strcspn(s, reject), (size_t)2,
				    "byte value %d", v);

		reject[0] = other;
		KUNIT_ASSERT_EQ_MSG(test, strcspn(s, reject), (size_t)5,
				    "byte value %d", v);
	}
}

/*
 * Long input: a match at index 255, 256 and 257 must be reported exactly,
 * which catches off-by-one and word-boundary mistakes.
 */
static void agent_strcspn_long_string(struct kunit *test)
{
	char buf[300];
	size_t i;

	for (i = 0; i < sizeof(buf) - 1; i++)
		buf[i] = 'a';
	buf[sizeof(buf) - 1] = '\0';

	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), (size_t)(sizeof(buf) - 1));

	for (i = 255; i <= 257; i++) {
		buf[i] = 'b';
		KUNIT_EXPECT_EQ_MSG(test, strcspn(buf, "b"), i,
				    "match at index %zu", i);
		buf[i] = 'a';
	}
}

/*
 * @s starts in the middle of a larger buffer: the result must not depend on
 * bytes before the start pointer, and must stop at the terminating NUL.
 */
static void agent_strcspn_offset_pointer(struct kunit *test)
{
	static const char buf[] = "xyzabcdef";
	const char *s = buf + 3;

	KUNIT_EXPECT_EQ(test, strcspn(s, "d"), (size_t)3);
	KUNIT_EXPECT_EQ(test, strcspn(s, "x"), (size_t)6);
	KUNIT_EXPECT_EQ(test, strcspn(s, "xyz"), (size_t)6);
}

/*
 * @reject terminates exactly after its last character: a character that only
 * appears past the NUL of @reject must not count as a match.
 */
static void agent_strcspn_reject_terminator(struct kunit *test)
{
	static const char reject_buf[] = { 'q', 0, 'w', 0 };

	KUNIT_EXPECT_EQ(test, strcspn("abcw", reject_buf), (size_t)4);
	KUNIT_EXPECT_EQ(test, strcspn("abcq", reject_buf), (size_t)3);
}

static struct kunit_case agent_strcspn_cases[] = {
	KUNIT_CASE(agent_strcspn_empty_s),
	KUNIT_CASE(agent_strcspn_empty_reject),
	KUNIT_CASE(agent_strcspn_both_empty),
	KUNIT_CASE(agent_strcspn_no_match),
	KUNIT_CASE(agent_strcspn_match_first),
	KUNIT_CASE(agent_strcspn_match_last),
	KUNIT_CASE(agent_strcspn_match_middle),
	KUNIT_CASE(agent_strcspn_earliest_match_wins),
	KUNIT_CASE(agent_strcspn_duplicate_reject),
	KUNIT_CASE(agent_strcspn_repeated_s),
	KUNIT_CASE(agent_strcspn_case_sensitive),
	KUNIT_CASE(agent_strcspn_single_char),
	KUNIT_CASE(agent_strcspn_high_bytes),
	KUNIT_CASE(agent_strcspn_all_byte_values),
	KUNIT_CASE(agent_strcspn_long_string),
	KUNIT_CASE(agent_strcspn_offset_pointer),
	KUNIT_CASE(agent_strcspn_reject_terminator),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_strcspn_cases,
};
kunit_test_suite(agent_test_suite);

MODULE_DESCRIPTION("KUnit test written by an agent");
MODULE_LICENSE("GPL");

// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/limits.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

/*
 * Call string_get_size() on a 32-byte buffer and check both the formatted
 * output and the return value (the length that would have been written).
 */
static void check_size(struct kunit *test, u64 size, u64 blk_size,
		       enum string_size_units units, const char *expected)
{
	char buf[32];
	int ret;

	ret = string_get_size(size, blk_size, units, buf, sizeof(buf));
	KUNIT_EXPECT_STREQ_MSG(test, buf, expected,
			       "size=%llu blk=%llu units=%#x",
			       size, blk_size, units);
	KUNIT_EXPECT_EQ_MSG(test, ret, (int)strlen(expected),
			    "size=%llu blk=%llu units=%#x",
			    size, blk_size, units);
}

static void agent_zero_size(struct kunit *test)
{
	check_size(test, 0, 1, STRING_UNITS_10, "0 B");
	check_size(test, 0, 1, STRING_UNITS_2, "0 B");
	check_size(test, 0, 512, STRING_UNITS_10, "0 B");
	check_size(test, 0, 512, STRING_UNITS_2, "0 B");
	check_size(test, 0, 1,
		   STRING_UNITS_10 | STRING_UNITS_NO_SPACE | STRING_UNITS_NO_BYTES,
		   "0");
}

static void agent_zero_block_size(struct kunit *test)
{
	/* A zero block size makes the total size zero, whatever @size is. */
	check_size(test, 1000, 0, STRING_UNITS_10, "0 B");
	check_size(test, 12345, 0, STRING_UNITS_2, "0 B");
	check_size(test, U64_MAX, 0, STRING_UNITS_10, "0 B");
}

static void agent_small_bytes(struct kunit *test)
{
	/* Below 1000 there is no unit prefix; precision depends on digit count. */
	check_size(test, 1, 1, STRING_UNITS_10, "1.00 B");
	check_size(test, 9, 1, STRING_UNITS_10, "9.00 B");
	check_size(test, 10, 1, STRING_UNITS_10, "10.0 B");
	check_size(test, 42, 1, STRING_UNITS_2, "42.0 B");
	check_size(test, 99, 1, STRING_UNITS_10, "99.0 B");
	check_size(test, 100, 1, STRING_UNITS_10, "100 B");
	check_size(test, 999, 1, STRING_UNITS_10, "999 B");
	check_size(test, 999, 1, STRING_UNITS_2, "999 B");
	check_size(test, 1023, 1, STRING_UNITS_2, "1023 B");
}

static void agent_decimal_boundaries(struct kunit *test)
{
	check_size(test, 999, 1, STRING_UNITS_10, "999 B");
	check_size(test, 1000, 1, STRING_UNITS_10, "1.00 kB");
	check_size(test, 1004, 1, STRING_UNITS_10, "1.00 kB");
	check_size(test, 1005, 1, STRING_UNITS_10, "1.01 kB");
	check_size(test, 1994, 1, STRING_UNITS_10, "1.99 kB");
	check_size(test, 1995, 1, STRING_UNITS_10, "2.00 kB");
	check_size(test, 1000000, 1, STRING_UNITS_10, "1.00 MB");
	check_size(test, 1000000000ULL, 1, STRING_UNITS_10, "1.00 GB");
	check_size(test, 1000000000000ULL, 1, STRING_UNITS_10, "1.00 TB");
	check_size(test, 1000000000000000ULL, 1, STRING_UNITS_10, "1.00 PB");
	check_size(test, 1000000000000000000ULL, 1, STRING_UNITS_10, "1.00 EB");
}

static void agent_binary_boundaries(struct kunit *test)
{
	check_size(test, 1023, 1, STRING_UNITS_2, "1023 B");
	check_size(test, 1024, 1, STRING_UNITS_2, "1.00 KiB");
	check_size(test, 1047552, 1, STRING_UNITS_2, "1023 KiB");
	check_size(test, 1048576, 1, STRING_UNITS_2, "1.00 MiB");
	check_size(test, 1073741824ULL, 1, STRING_UNITS_2, "1.00 GiB");
	check_size(test, 1099511627776ULL, 1, STRING_UNITS_2, "1.00 TiB");
	check_size(test, 1125899906842624ULL, 1, STRING_UNITS_2, "1.00 PiB");
	check_size(test, 1ULL << 60, 1, STRING_UNITS_2, "1.00 EiB");
}

static void agent_decimal_rounding(struct kunit *test)
{
	check_size(test, 1500, 1, STRING_UNITS_10, "1.50 kB");
	check_size(test, 1499, 1, STRING_UNITS_10, "1.50 kB");
	check_size(test, 2500, 1, STRING_UNITS_10, "2.50 kB");
	check_size(test, 12345, 1, STRING_UNITS_10, "12.3 kB");
	check_size(test, 1234567, 1, STRING_UNITS_10, "1.23 MB");
	check_size(test, 123456, 1, STRING_UNITS_10, "123 kB");
}

static void agent_binary_rounding(struct kunit *test)
{
	/* 1000 bytes is below 1 KiB, so it stays in bytes. */
	check_size(test, 1000, 1, STRING_UNITS_2, "1000 B");
	check_size(test, 1025, 1, STRING_UNITS_2, "1.00 KiB");
	check_size(test, 1029, 1, STRING_UNITS_2, "1.00 KiB");
	check_size(test, 1030, 1, STRING_UNITS_2, "1.01 KiB");
	check_size(test, 1536, 1, STRING_UNITS_2, "1.50 KiB");
	/* 2047 bytes is 1.999 KiB, which rounds up into the next digit. */
	check_size(test, 2047, 1, STRING_UNITS_2, "2.00 KiB");
	check_size(test, 4294967295ULL, 1, STRING_UNITS_2, "4.00 GiB");
}

static void agent_digit_precision(struct kunit *test)
{
	/* Digits shown depend on how many integer digits there are: 3 sig figs. */
	check_size(test, 9000, 1, STRING_UNITS_10, "9.00 kB");
	check_size(test, 10000, 1, STRING_UNITS_10, "10.0 kB");
	check_size(test, 99000, 1, STRING_UNITS_10, "99.0 kB");
	check_size(test, 100000, 1, STRING_UNITS_10, "100 kB");
	check_size(test, 10240, 1, STRING_UNITS_2, "10.0 KiB");
	check_size(test, 9216, 1, STRING_UNITS_2, "9.00 KiB");
	check_size(test, 102400, 1, STRING_UNITS_2, "100 KiB");
}

static void agent_carry_into_next_digit(struct kunit *test)
{
	/* Rounding can carry into the integer part and lengthen the output. */
	check_size(test, 9995, 1, STRING_UNITS_10, "10.00 kB");
	check_size(test, 9999, 1, STRING_UNITS_10, "10.00 kB");
	check_size(test, 99950, 1, STRING_UNITS_10, "100.0 kB");
	check_size(test, 99999, 1, STRING_UNITS_10, "100.0 kB");
	check_size(test, 10236, 1, STRING_UNITS_2, "10.00 KiB");
}

static void agent_large_values(struct kunit *test)
{
	/* Crosses the 32-bit boundary where the reduction loop kicks in. */
	check_size(test, 4294967295ULL, 1, STRING_UNITS_10, "4.29 GB");
	check_size(test, 4294967296ULL, 1, STRING_UNITS_10, "4.29 GB");
	/* U64_MAX bytes is just under 16 EiB, shown as 16.0 after rounding. */
	check_size(test, U64_MAX, 1, STRING_UNITS_2, "16.0 EiB");
	check_size(test, U64_MAX, 1, STRING_UNITS_10, "18.4 EB");
}

static void agent_block_size(struct kunit *test)
{
	/* Total is size * blk_size, so 2 * 512 bytes is 1024 bytes. */
	check_size(test, 2, 512, STRING_UNITS_10, "1.02 kB");
	check_size(test, 1, 1024, STRING_UNITS_2, "1.00 KiB");
	check_size(test, 1, 1000000, STRING_UNITS_10, "1.00 MB");
	/* A block size wider than 32 bits takes the block reduction path. */
	check_size(test, 1, 1ULL << 32, STRING_UNITS_10, "4.29 GB");
	check_size(test, 1, 1ULL << 32, STRING_UNITS_2, "4.00 GiB");
}

static void agent_flags(struct kunit *test)
{
	const u32 no_space = STRING_UNITS_NO_SPACE;
	const u32 no_bytes = STRING_UNITS_NO_BYTES;

	check_size(test, 1000, 1, STRING_UNITS_10 | no_space, "1.00kB");
	check_size(test, 1024, 1, STRING_UNITS_2 | no_space, "1.00KiB");
	check_size(test, 1000, 1, STRING_UNITS_10 | no_bytes, "1.00 k");
	check_size(test, 1000, 1, STRING_UNITS_10 | no_space | no_bytes, "1.00k");
	check_size(test, 1024, 1, STRING_UNITS_2 | no_space | no_bytes, "1.00Ki");
	check_size(test, 999, 1, STRING_UNITS_10 | no_space | no_bytes, "999");
	check_size(test, 999, 1, STRING_UNITS_10 | no_space, "999B");
}

static void agent_unknown_unit(struct kunit *test)
{
	/*
	 * Both operands are huge, so the exponent runs past the table of
	 * prefixes and the unit must fall back to "UNK".
	 */
	char buf[32];
	int ret;

	ret = string_get_size(U64_MAX, U64_MAX, STRING_UNITS_10, buf, sizeof(buf));
	KUNIT_EXPECT_TRUE_MSG(test, strstr(buf, "UNKB") != NULL,
			      "buf=\"%s\"", buf);
	KUNIT_EXPECT_EQ(test, ret, (int)strlen(buf));

	ret = string_get_size(U64_MAX, U64_MAX, STRING_UNITS_2, buf, sizeof(buf));
	KUNIT_EXPECT_TRUE_MSG(test, strstr(buf, "UNKB") != NULL,
			      "buf=\"%s\"", buf);
	KUNIT_EXPECT_EQ(test, ret, (int)strlen(buf));
}

static void agent_truncation(struct kunit *test)
{
	char buf[16];
	int ret;

	/* Fits exactly: 8 characters plus the terminating NUL. */
	ret = string_get_size(1536, 1, STRING_UNITS_2, buf, 9);
	KUNIT_EXPECT_STREQ(test, buf, "1.50 KiB");
	KUNIT_EXPECT_EQ(test, ret, 8);

	/* Truncated by one: the NUL lands in the last slot. */
	ret = string_get_size(1536, 1, STRING_UNITS_2, buf, 8);
	KUNIT_EXPECT_STREQ(test, buf, "1.50 Ki");
	KUNIT_EXPECT_EQ(test, ret, 8);

	/* Heavily truncated, but the return value still reports the full length. */
	ret = string_get_size(1536, 1, STRING_UNITS_2, buf, 4);
	KUNIT_EXPECT_STREQ(test, buf, "1.5");
	KUNIT_EXPECT_EQ(test, ret, 8);

	/* Zero length writes nothing; the buffer must stay untouched. */
	strscpy(buf, "sentinel", sizeof(buf));
	ret = string_get_size(1536, 1, STRING_UNITS_2, buf, 0);
	KUNIT_EXPECT_STREQ(test, buf, "sentinel");
	KUNIT_EXPECT_EQ(test, ret, 8);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_zero_size),
	KUNIT_CASE(agent_zero_block_size),
	KUNIT_CASE(agent_small_bytes),
	KUNIT_CASE(agent_decimal_boundaries),
	KUNIT_CASE(agent_binary_boundaries),
	KUNIT_CASE(agent_decimal_rounding),
	KUNIT_CASE(agent_binary_rounding),
	KUNIT_CASE(agent_digit_precision),
	KUNIT_CASE(agent_carry_into_next_digit),
	KUNIT_CASE(agent_large_values),
	KUNIT_CASE(agent_block_size),
	KUNIT_CASE(agent_flags),
	KUNIT_CASE(agent_unknown_unit),
	KUNIT_CASE(agent_truncation),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

