#include <kunit/test.h>
#include <linux/minmax.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

#define BUF_SZ		64
#define CANARY		0xa5
#define HEX_DIGITS	"0123456789abcdef"

/*
 * Run string_escape_mem() into a canary-filled buffer of @osz bytes and check
 * the return value, the bytes actually written, and that nothing past the
 * written bytes was touched.
 */
static void check_escape_at(struct kunit *test, const char *src, size_t isz,
			    unsigned int flags, const char *only,
			    const char *expected, size_t elen, size_t osz)
{
	char buf[BUF_SZ];
	size_t written = min_t(size_t, osz, elen);
	bool clobbered = false;
	size_t i;
	int ret;

	memset(buf, CANARY, sizeof(buf));
	ret = string_escape_mem(src, isz, buf, osz, flags, only);

	KUNIT_EXPECT_EQ(test, ret, (int)elen);
	KUNIT_EXPECT_MEMEQ(test, buf, expected, written);
	for (i = written; i < sizeof(buf); i++)
		clobbered |= buf[i] != CANARY;
	KUNIT_EXPECT_FALSE(test, clobbered);
}

#define CHECK_ESCAPE(test, src, flags, only, expected)				\
	check_escape_at(test, src, sizeof(src) - 1, flags, only,		\
			expected, sizeof(expected) - 1, BUF_SZ)

static void test_empty_input(struct kunit *test)
{
	check_escape_at(test, "x", 0, ESCAPE_ANY_NP, NULL, "", 0, BUF_SZ);
	check_escape_at(test, "", 0, ESCAPE_ANY_NP | ESCAPE_HEX, NULL, "", 0, BUF_SZ);
}

static void test_passthrough_no_flags(struct kunit *test)
{
	CHECK_ESCAPE(test, "abc\n\x01\xff", 0, NULL, "abc\n\x01\xff");
}

static void test_space_class(struct kunit *test)
{
	CHECK_ESCAPE(test, "\f\n\r\t\v", ESCAPE_SPACE, NULL, "\\f\\n\\r\\t\\v");
}

static void test_space_class_not_selected(struct kunit *test)
{
	CHECK_ESCAPE(test, " \n\t\r", ESCAPE_SPECIAL, NULL, " \n\t\r");
}

static void test_np_without_fallback_class(struct kunit *test)
{
	/* Non-printable bytes with no class to catch them pass through. */
	CHECK_ESCAPE(test, "a\x01\x80", ESCAPE_NP, NULL, "a\x01\x80");
}

static void test_special_class(struct kunit *test)
{
	CHECK_ESCAPE(test, "\"\\\a\033", ESCAPE_SPECIAL, NULL, "\\\"\\\\\\a\\e");
}

static void test_null_class(struct kunit *test)
{
	check_escape_at(test, "a\0b", 3, ESCAPE_NULL, NULL, "a\\0b", 4, BUF_SZ);
}

static void test_null_before_octal(struct kunit *test)
{
	/* ESCAPE_NULL is checked before ESCAPE_OCTAL. */
	check_escape_at(test, "\0\x01", 2, ESCAPE_NULL | ESCAPE_OCTAL, NULL,
			"\\0\\001", 6, BUF_SZ);
}

static void test_octal_class(struct kunit *test)
{
	check_escape_at(test, "\x00\x07\x7f\x80\xff", 5, ESCAPE_OCTAL, NULL,
			"\\000\\007\\177\\200\\377", 20, BUF_SZ);
}

static void test_hex_class(struct kunit *test)
{
	check_escape_at(test, "\x00\x09\x1f\xff", 4, ESCAPE_HEX, NULL,
			"\\x00\\x09\\x1f\\xff", 16, BUF_SZ);
}

static void test_octal_wins_over_hex(struct kunit *test)
{
	/* ESCAPE_OCTAL is checked before ESCAPE_HEX and covers every byte. */
	check_escape_at(test, "\x01\xff", 2, ESCAPE_OCTAL | ESCAPE_HEX, NULL,
			"\\001\\377", 8, BUF_SZ);
}

static void test_np_class(struct kunit *test)
{
	/* 0x20..0x7e are printable; 0x01, 0x85 and 0x7f are not. */
	check_escape_at(test, "a\x01\x85 ~\x7f", 6, ESCAPE_NP | ESCAPE_OCTAL,
			NULL, "a\\001\\205 ~\\177", 15, BUF_SZ);
}

static void test_na_class(struct kunit *test)
{
	/* 0x7f is ASCII, so only bytes >= 0x80 are escaped. */
	CHECK_ESCAPE(test, "a\x7f\x80\xc3", ESCAPE_NA | ESCAPE_HEX, NULL,
		     "a\x7f\\x80\\xc3");
}

static void test_nap_class(struct kunit *test)
{
	/* Printable ASCII passes; '\n', 0x01 and 0x80 fall to OCTAL. */
	CHECK_ESCAPE(test, "A\n\x80~ \x01", ESCAPE_NAP | ESCAPE_OCTAL, NULL,
		     "A\\012\\200~ \\001");
}

static void test_np_beats_special(struct kunit *test)
{
	/*
	 * Printable bytes pass through the NP check before the SPECIAL check
	 * gets a chance, so '"' and '\' stay raw; '\n' is caught by SPACE.
	 */
	CHECK_ESCAPE(test, "a\"b\\c\n\x01", ESCAPE_ANY_NP, NULL,
		     "a\"b\\c\\n\\001");
}

static void test_only_limits_escaping(struct kunit *test)
{
	/* Only bytes listed in @only are escaped; the rest pass through. */
	CHECK_ESCAPE(test, "abc\n", ESCAPE_OCTAL, "ab", "\\141\\142c\n");
}

static void test_only_without_append(struct kunit *test)
{
	/*
	 * Without ESCAPE_APPEND, a byte in @only that NP would pass through
	 * stays raw, and bytes not in @only are never escaped.
	 */
	CHECK_ESCAPE(test, "xa\x01", ESCAPE_NP | ESCAPE_HEX, "x", "xa\x01");
	CHECK_ESCAPE(test, "xay", ESCAPE_HEX, "x", "\\x78ay");
}

static void test_only_with_append(struct kunit *test)
{
	/*
	 * With ESCAPE_APPEND, bytes in @only are escaped by the given classes
	 * even when they would otherwise pass through.
	 */
	CHECK_ESCAPE(test, "xa\x01", ESCAPE_NP | ESCAPE_HEX | ESCAPE_APPEND,
		     "x", "\\x78a\\x01");
}

static void test_only_empty_matches_null(struct kunit *test)
{
	CHECK_ESCAPE(test, "a\n\x01", ESCAPE_OCTAL, "", "\\141\\012\\001");
	CHECK_ESCAPE(test, "a\n\x01", ESCAPE_OCTAL, NULL, "\\141\\012\\001");
}

static void test_isz_limits_input(struct kunit *test)
{
	/* The '\n' past isz must not be read. */
	check_escape_at(test, "ab\n", 2, ESCAPE_SPACE, NULL, "ab", 2, BUF_SZ);
	check_escape_at(test, "\n", 0, ESCAPE_ANY, NULL, "", 0, BUF_SZ);
}

static void test_size_query_null_dst(struct kunit *test)
{
	/* A NULL dst with osz 0 computes the length without writing. */
	KUNIT_EXPECT_EQ(test,
			string_escape_mem("\n\x01", 2, NULL, 0, ESCAPE_ANY, NULL),
			6);
	KUNIT_EXPECT_EQ(test,
			string_escape_mem("abc", 3, NULL, 0, 0, NULL), 3);
}

static void test_exact_fit(struct kunit *test)
{
	/* osz equal to the output length must write everything. */
	check_escape_at(test, "\n", 1, ESCAPE_SPACE, NULL, "\\n", 2, 2);
}

static void test_truncated_by_one(struct kunit *test)
{
	/* One byte short: only the first byte is written, length still 2. */
	check_escape_at(test, "\n", 1, ESCAPE_SPACE, NULL, "\\n", 2, 1);
}

static void test_zero_osz(struct kunit *test)
{
	check_escape_at(test, "\n", 1, ESCAPE_SPACE, NULL, "\\n", 2, 0);
}

static void test_truncated_mid_escape(struct kunit *test)
{
	check_escape_at(test, "\x01", 1, ESCAPE_OCTAL, NULL, "\\001", 4, 2);
	check_escape_at(test, "\x01", 1, ESCAPE_OCTAL, NULL, "\\001", 4, 3);
}

static void test_osz_sweep(struct kunit *test)
{
	static const char src[] = "a\n\x01\"\\\x80";
	const unsigned int flags = ESCAPE_ANY | ESCAPE_HEX;
	char full[BUF_SZ];
	int n, osz;

	n = string_escape_mem(src, sizeof(src) - 1, full, sizeof(full),
			      flags, NULL);
	KUNIT_ASSERT_LT(test, (size_t)n, sizeof(full));

	for (osz = 0; osz <= n + 2; osz++)
		check_escape_at(test, src, sizeof(src) - 1, flags, NULL,
				full, n, osz);
}

static void test_every_byte_octal(struct kunit *test)
{
	char buf[BUF_SZ];
	unsigned int c;

	for (c = 0; c < 256; c++) {
		char in = c;
		char exp[4] = { '\\', '0' + ((c >> 6) & 7),
				'0' + ((c >> 3) & 7), '0' + (c & 7) };
		int ret = string_escape_mem(&in, 1, buf, sizeof(buf),
					    ESCAPE_OCTAL, NULL);

		KUNIT_EXPECT_EQ_MSG(test, ret, 4, "byte %u", c);
		KUNIT_EXPECT_EQ_MSG(test, memcmp(buf, exp, 4), 0,
				    "byte %u", c);
	}
}

static void test_every_byte_hex(struct kunit *test)
{
	char buf[BUF_SZ];
	unsigned int c;

	for (c = 0; c < 256; c++) {
		char in = c;
		char exp[4] = { '\\', 'x', HEX_DIGITS[c >> 4], HEX_DIGITS[c & 15] };
		int ret = string_escape_mem(&in, 1, buf, sizeof(buf),
					    ESCAPE_HEX, NULL);

		KUNIT_EXPECT_EQ_MSG(test, ret, 4, "byte %u", c);
		KUNIT_EXPECT_EQ_MSG(test, memcmp(buf, exp, 4), 0,
				    "byte %u", c);
	}
}

static void test_every_byte_np_octal(struct kunit *test)
{
	char buf[BUF_SZ];
	unsigned int c;

	for (c = 0; c < 256; c++) {
		char in = c;
		/* isprint() is ASCII 0x20..0x7e plus Latin-1 0xa0..0xff. */
		bool printable = (c >= 0x20 && c <= 0x7e) || c >= 0xa0;
		char exp[4] = { '\\', '0' + ((c >> 6) & 7),
				'0' + ((c >> 3) & 7), '0' + (c & 7) };
		int ret = string_escape_mem(&in, 1, buf, sizeof(buf),
					    ESCAPE_NP | ESCAPE_OCTAL, NULL);

		if (printable) {
			KUNIT_EXPECT_EQ_MSG(test, ret, 1, "byte %u", c);
			KUNIT_EXPECT_EQ_MSG(test, (unsigned int)(unsigned char)buf[0],
					    c, "byte %u", c);
		} else {
			KUNIT_EXPECT_EQ_MSG(test, ret, 4, "byte %u", c);
			KUNIT_EXPECT_EQ_MSG(test, memcmp(buf, exp, 4), 0,
					    "byte %u", c);
		}
	}
}

static void test_every_byte_na_hex(struct kunit *test)
{
	char buf[BUF_SZ];
	unsigned int c;

	for (c = 0; c < 256; c++) {
		char in = c;
		char exp[4] = { '\\', 'x', HEX_DIGITS[c >> 4], HEX_DIGITS[c & 15] };
		int ret = string_escape_mem(&in, 1, buf, sizeof(buf),
					    ESCAPE_NA | ESCAPE_HEX, NULL);

		if (c < 0x80) {
			KUNIT_EXPECT_EQ_MSG(test, ret, 1, "byte %u", c);
			KUNIT_EXPECT_EQ_MSG(test, (unsigned int)(unsigned char)buf[0],
					    c, "byte %u", c);
		} else {
			KUNIT_EXPECT_EQ_MSG(test, ret, 4, "byte %u", c);
			KUNIT_EXPECT_EQ_MSG(test, memcmp(buf, exp, 4), 0,
					    "byte %u", c);
		}
	}
}

static void test_long_input(struct kunit *test)
{
	const size_t isz = 1024;
	const size_t osz = isz * 4;
	unsigned char *src;
	char *dst;
	size_t i, mismatches = 0;
	int ret;

	src = kunit_kmalloc(test, isz, GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, src);
	dst = kunit_kmalloc(test, osz, GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, dst);

	for (i = 0; i < isz; i++)
		src[i] = i;

	ret = string_escape_mem(src, isz, dst, osz, ESCAPE_OCTAL, NULL);
	KUNIT_EXPECT_EQ(test, ret, (int)osz);

	for (i = 0; i < isz; i++) {
		char exp[4] = { '\\', '0' + ((src[i] >> 6) & 7),
				'0' + ((src[i] >> 3) & 7), '0' + (src[i] & 7) };

		if (memcmp(&dst[i * 4], exp, 4))
			mismatches++;
	}
	KUNIT_EXPECT_EQ(test, mismatches, 0);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(test_empty_input),
	KUNIT_CASE(test_passthrough_no_flags),
	KUNIT_CASE(test_space_class),
	KUNIT_CASE(test_space_class_not_selected),
	KUNIT_CASE(test_np_without_fallback_class),
	KUNIT_CASE(test_special_class),
	KUNIT_CASE(test_null_class),
