	KUNIT_CASE(test_np_beats_special),
	KUNIT_CASE(test_only_limits_escaping),
	KUNIT_CASE(test_only_without_append),
	KUNIT_CASE(test_only_with_append),
	KUNIT_CASE(test_only_empty_matches_null),
	KUNIT_CASE(test_isz_limits_input),
	KUNIT_CASE(test_size_query_null_dst),
	KUNIT_CASE(test_exact_fit),
	KUNIT_CASE(test_truncated_by_one),
	KUNIT_CASE(test_zero_osz),
	KUNIT_CASE(test_truncated_mid_escape),
	KUNIT_CASE(test_osz_sweep),
