// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/kernel.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

#define AGENT_BUF_SIZE 64

/* Returns true if buf[from..len) still holds the 'x' fill pattern. */
static bool agent_tail_untouched(const char *buf, size_t from, size_t len)
{
	size_t i;

	for (i = from; i < len; i++) {
		if (buf[i] != 'x')
			return false;
	}
	return true;
}

/* Unbounded unescape of @in must produce @want and return strlen(@want). */
static void expect_unescape(struct kunit *test, const char *in,
			    unsigned int flags, const char *want)
{
	char src[AGENT_BUF_SIZE];
	char dst[AGENT_BUF_SIZE];
	int ret;

	KUNIT_ASSERT_LT(test, strlen(in), sizeof(src));
	strscpy(src, in, sizeof(src));
	memset(dst, 'x', sizeof(dst));

	ret = string_unescape(src, dst, 0, flags);
	KUNIT_EXPECT_EQ(test, ret, (int)strlen(want));
	KUNIT_EXPECT_STREQ(test, dst, want);
	KUNIT_EXPECT_TRUE(test, agent_tail_untouched(dst, ret + 1, sizeof(dst)));
}

/* Bounded unescape of @in into a @size byte destination. */
static void expect_unescape_sized(struct kunit *test, const char *in,
				  unsigned int flags, size_t size,
				  const char *want)
{
	char src[AGENT_BUF_SIZE];
	char dst[AGENT_BUF_SIZE];
	int ret;

	KUNIT_ASSERT_LT(test, strlen(in), sizeof(src));
	KUNIT_ASSERT_LE(test, size, sizeof(dst));
	strscpy(src, in, sizeof(src));
	memset(dst, 'x', sizeof(dst));

	ret = string_unescape(src, dst, size, flags);
	KUNIT_EXPECT_EQ(test, ret, (int)strlen(want));
	KUNIT_EXPECT_STREQ(test, dst, want);
	KUNIT_EXPECT_TRUE(test, agent_tail_untouched(dst, ret + 1, sizeof(dst)));
}

static void unescape_empty(struct kunit *test)
{
	expect_unescape(test, "", UNESCAPE_ANY, "");
	expect_unescape(test, "", 0, "");
}

static void unescape_plain_text(struct kunit *test)
{
	expect_unescape(test, "h", UNESCAPE_ANY, "h");
	expect_unescape(test, "hello, world", UNESCAPE_ANY, "hello, world");
	expect_unescape(test, "hello, world", 0, "hello, world");
}

static void unescape_no_flags_keeps_escapes(struct kunit *test)
{
	/* With no flags every escape is copied through verbatim. */
	expect_unescape(test, "\\n\\t\\x41\\101\\\"\\\\\\a\\e\\f\\r\\v\\q", 0,
			"\\n\\t\\x41\\101\\\"\\\\\\a\\e\\f\\r\\v\\q");
}

static void unescape_special_escapes(struct kunit *test)
{
	expect_unescape(test, "\\\"", UNESCAPE_SPECIAL, "\"");
	expect_unescape(test, "\\\\", UNESCAPE_SPECIAL, "\\");
	expect_unescape(test, "\\a", UNESCAPE_SPECIAL, "\a");
	expect_unescape(test, "\\e", UNESCAPE_SPECIAL, "\x1b");
	expect_unescape(test, "\\\"\\\\\\a\\e", UNESCAPE_SPECIAL,
			"\"\\\a\x1b");
}

static void unescape_space_escapes(struct kunit *test)
{
	expect_unescape(test, "\\f\\n\\r\\t\\v", UNESCAPE_SPACE,
			"\f\n\r\t\v");
	expect_unescape(test, "\\n\\n\\n", UNESCAPE_SPACE, "\n\n\n");
}

static void unescape_octal_escapes(struct kunit *test)
{
	expect_unescape(test, "\\101", UNESCAPE_OCTAL, "A");
	expect_unescape(test, "\\101\\102", UNESCAPE_OCTAL, "AB");
	expect_unescape(test, "\\1", UNESCAPE_OCTAL, "\001");
	expect_unescape(test, "\\12", UNESCAPE_OCTAL, "\n");
	expect_unescape(test, "\\377", UNESCAPE_OCTAL, "\xff");
	/* At most three digits are consumed. */
	expect_unescape(test, "\\1234", UNESCAPE_OCTAL, "S4");
	expect_unescape(test, "\\1012", UNESCAPE_OCTAL, "A2");
}

static void unescape_octal_invalid(struct kunit *test)
{
	expect_unescape(test, "\\8", UNESCAPE_OCTAL, "\\8");
	expect_unescape(test, "\\8\\9", UNESCAPE_OCTAL, "\\8\\9");
	expect_unescape(test, "\\18", UNESCAPE_OCTAL, "\001" "8");
}

static void unescape_hex_escapes(struct kunit *test)
{
	expect_unescape(test, "\\x41", UNESCAPE_HEX, "A");
	expect_unescape(test, "\\xab", UNESCAPE_HEX, "\xab");
	expect_unescape(test, "\\x7f", UNESCAPE_HEX, "\x7f");
	expect_unescape(test, "\\xff", UNESCAPE_HEX, "\xff");
	/* Only two digits are consumed. */
	expect_unescape(test, "\\x414", UNESCAPE_HEX, "A4");
	/* A single digit is enough. */
	expect_unescape(test, "\\x4", UNESCAPE_HEX, "\x04");
	expect_unescape(test, "\\xAG", UNESCAPE_HEX, "\nG");
	expect_unescape(test, "\\x41\\x42\\x43", UNESCAPE_HEX, "ABC");
}

static void unescape_hex_invalid(struct kunit *test)
{
	expect_unescape(test, "\\xg", UNESCAPE_HEX, "\\xg");
	expect_unescape(test, "\\xz", UNESCAPE_HEX, "\\xz");
	expect_unescape(test, "\\x", UNESCAPE_HEX, "\\x");
	expect_unescape(test, "\\X41", UNESCAPE_HEX, "\\X41");
}

static void unescape_unknown_escapes(struct kunit *test)
{
	expect_unescape(test, "\\q", UNESCAPE_ANY, "\\q");
	expect_unescape(test, "\\b", UNESCAPE_ANY, "\\b");
	expect_unescape(test, "\\?\\'", UNESCAPE_ANY, "\\?\\'");
	expect_unescape(test, "\\q\\b", UNESCAPE_ANY, "\\q\\b");
}

static void unescape_trailing_backslash(struct kunit *test)
{
	expect_unescape(test, "\\", UNESCAPE_ANY, "\\");
	expect_unescape(test, "abc\\", UNESCAPE_ANY, "abc\\");
	expect_unescape(test, "\\", 0, "\\");
}

static void unescape_escaped_backslash(struct kunit *test)
{
	/* "\\n" in the input is a backslash followed by a plain 'n'. */
	expect_unescape(test, "\\\\n", UNESCAPE_ANY, "\\n");
	expect_unescape(test, "\\\\\\\\", UNESCAPE_SPECIAL, "\\\\");
	/* Without UNESCAPE_SPECIAL the escaped backslash is kept as-is. */
	expect_unescape(test, "\\\\x41", UNESCAPE_HEX, "\\\\x41");
}

static void unescape_mixed_sequence(struct kunit *test)
{
	expect_unescape(test, "a\\tb\\x41c\\101", UNESCAPE_ANY, "a\tbAcA");
	expect_unescape(test, "\\\"x\\\"\\x21", UNESCAPE_ANY, "\"x\"!");
}

static void unescape_flags_are_independent(struct kunit *test)
{
	expect_unescape(test, "\\n\\\"", UNESCAPE_SPECIAL, "\\n\"");
	expect_unescape(test, "\\n\\\"", UNESCAPE_SPACE, "\n\\\"");
	expect_unescape(test, "\\101\\x41", UNESCAPE_OCTAL, "A\\x41");
	expect_unescape(test, "\\101\\x41", UNESCAPE_HEX, "\\101A");
	expect_unescape(test, "\\a", UNESCAPE_SPACE, "\\a");
	expect_unescape(test, "\\a", UNESCAPE_SPECIAL, "\a");
	expect_unescape(test, "\\n", UNESCAPE_OCTAL, "\\n");
	expect_unescape(test, "\\x41", UNESCAPE_OCTAL | UNESCAPE_SPECIAL,
			"\\x41");
}

static void unescape_size_truncates_plain_text(struct kunit *test)
{
	/* The destination holds size - 1 characters plus the NUL. */
	expect_unescape_sized(test, "hello", 0, 1, "");
	expect_unescape_sized(test, "hello", 0, 2, "h");
	expect_unescape_sized(test, "hello", 0, 3, "he");
	expect_unescape_sized(test, "hello", 0, 5, "hell");
	expect_unescape_sized(test, "hello", 0, 6, "hello");
	expect_unescape_sized(test, "hello", 0, 7, "hello");
}

static void unescape_size_fits_escape(struct kunit *test)
{
	expect_unescape_sized(test, "\\n", UNESCAPE_SPACE, 3, "\n");
	expect_unescape_sized(test, "\\x41", UNESCAPE_HEX, 3, "A");
	expect_unescape_sized(test, "\\x41\\x42", UNESCAPE_HEX, 5, "AB");
}

/*
 * For any size, the output must be NUL-terminated within the buffer, the
 * return value must equal the length written and stay below size, and no
 * byte past the NUL may be touched. With size = strlen(in) + 1 the result
 * must match the unbounded one.
 */
static void unescape_size_bounds(struct kunit *test)
{
	static const char * const inputs[] = {
		"a\\tb\\x41c\\101d",
		"\\\\n\\\"",
		"\\x4\\x4g",
		"\\",
		"\\\\\\",
		"\\q\\8\\xz\\",
	};
	char src[AGENT_BUF_SIZE];
	char full[AGENT_BUF_SIZE];
	char dst[AGENT_BUF_SIZE];
	size_t i, size, len;
	int full_ret, ret;

	for (i = 0; i < ARRAY_SIZE(inputs); i++) {
		len = strlen(inputs[i]);
		strscpy(src, inputs[i], sizeof(src));
		memset(full, 'x', sizeof(full));
		full_ret = string_unescape(src, full, 0, UNESCAPE_ANY);
		KUNIT_ASSERT_EQ(test, full_ret, (int)strlen(full));

		for (size = 1; size <= len + 1; size++) {
			memset(dst, 'x', sizeof(dst));
			ret = string_unescape(src, dst, size, UNESCAPE_ANY);

			KUNIT_EXPECT_EQ(test, ret, (int)strlen(dst));
			KUNIT_EXPECT_LT(test, ret, (int)size);
			KUNIT_EXPECT_TRUE(test,
					  agent_tail_untouched(dst, ret + 1,
							       sizeof(dst)));
		}

		memset(dst, 'x', sizeof(dst));
		ret = string_unescape(src, dst, len + 1, UNESCAPE_ANY);
		KUNIT_EXPECT_EQ(test, ret, full_ret);
		KUNIT_EXPECT_STREQ(test, dst, full);
	}
}

static void unescape_inplace(struct kunit *test)
{
	char buf[AGENT_BUF_SIZE] = "a\\x42\\tc";
	int ret;

	ret = string_unescape_inplace(buf, UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_STREQ(test, buf, "aB\tc");

	strscpy(buf, "\\101\\x42\\\"", sizeof(buf));
	ret = string_unescape_inplace(buf, UNESCAPE_OCTAL | UNESCAPE_HEX);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_STREQ(test, buf, "AB\\\"");
}

static void unescape_any_wrappers(struct kunit *test)
{
	char src[AGENT_BUF_SIZE] = "\\x41\\n";
	char dst[AGENT_BUF_SIZE];
	char buf[AGENT_BUF_SIZE] = "\\101\\x42";
	int ret;

	memset(dst, 'x', sizeof(dst));
	ret = string_unescape_any(src, dst, 0);
	KUNIT_EXPECT_EQ(test, ret, 2);
	KUNIT_EXPECT_STREQ(test, dst, "A\n");

	ret = string_unescape_any_inplace(buf);
	KUNIT_EXPECT_EQ(test, ret, 2);
	KUNIT_EXPECT_STREQ(test, buf, "AB");
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(unescape_empty),
	KUNIT_CASE(unescape_plain_text),
	KUNIT_CASE(unescape_no_flags_keeps_escapes),
	KUNIT_CASE(unescape_special_escapes),
	KUNIT_CASE(unescape_space_escapes),
	KUNIT_CASE(unescape_octal_escapes),
	KUNIT_CASE(unescape_octal_invalid),
	KUNIT_CASE(unescape_hex_escapes),
	KUNIT_CASE(unescape_hex_invalid),
	KUNIT_CASE(unescape_unknown_escapes),
	KUNIT_CASE(unescape_trailing_backslash),
	KUNIT_CASE(unescape_escaped_backslash),
	KUNIT_CASE(unescape_mixed_sequence),
	KUNIT_CASE(unescape_flags_are_independent),
	KUNIT_CASE(unescape_size_truncates_plain_text),
	KUNIT_CASE(unescape_size_fits_escape),
	KUNIT_CASE(unescape_size_bounds),
	KUNIT_CASE(unescape_inplace),
	KUNIT_CASE(unescape_any_wrappers),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

