#include <linux/string.h>

#define SENTINEL 0x5a5a

/*
 * Run get_option() on @input and check the return value, the parsed
 * integer and the string left over after parsing.
 */
static void check_option(struct kunit *test, const char *input,
			 int expect_ret, int expect_val, const char *expect_rest)
{
	char *str = (char *)input;
	int pint = SENTINEL;
	int ret;

	ret = get_option(&str, &pint);
	KUNIT_EXPECT_EQ(test, ret, expect_ret);
	KUNIT_EXPECT_EQ(test, pint, expect_val);
	KUNIT_EXPECT_STREQ(test, str, expect_rest);
}

static void get_option_null_string_ptr(struct kunit *test)
{
	char *str = NULL;
	int pint = SENTINEL;

	KUNIT_EXPECT_EQ(test, get_option(&str, &pint), 0);
	KUNIT_EXPECT_EQ(test, pint, SENTINEL);
	KUNIT_EXPECT_NULL(test, str);
}

static void get_option_empty_string(struct kunit *test)
{
	int pint = SENTINEL;
	char *str = "";

	KUNIT_EXPECT_EQ(test, get_option(&str, &pint), 0);
	KUNIT_EXPECT_EQ(test, pint, SENTINEL);
	KUNIT_EXPECT_STREQ(test, str, "");
}

static void get_option_single_digit(struct kunit *test)
{
	check_option(test, "7", 1, 7, "");
}

static void get_option_multi_digit(struct kunit *test)
{
	check_option(test, "1234", 1, 1234, "");
	check_option(test, "99", 1, 99, "");
	check_option(test, "10", 1, 10, "");
}

static void get_option_zero(struct kunit *test)
{
	check_option(test, "0", 1, 0, "");
	check_option(test, "00", 1, 0, "");
}

static void get_option_stops_at_non_digit(struct kunit *test)
{
	check_option(test, "42abc", 1, 42, "abc");
	check_option(test, "5 ", 1, 5, " ");
}

static void get_option_no_digits(struct kunit *test)
{
	/* No integer: return 0, value is zeroed, string is not advanced. */
	check_option(test, "abc", 0, 0, "abc");
	check_option(test, "x9", 0, 0, "x9");
}

static void get_option_leading_space_not_skipped(struct kunit *test)
{
	check_option(test, " 5", 0, 0, " 5");
}

static void get_option_comma(struct kunit *test)
{
	/* Comma: return 2 and consume exactly the comma. */
	check_option(test, "5,9", 2, 5, "9");
	check_option(test, "0,0", 2, 0, "0");
}

static void get_option_trailing_comma(struct kunit *test)
{
	check_option(test, "5,", 2, 5, "");
}

static void get_option_double_comma(struct kunit *test)
{
	/* Only one comma is consumed; the second one is left for the caller. */
	check_option(test, "5,,6", 2, 5, ",6");
}

static void get_option_range(struct kunit *test)
{
	/* Hyphen: return 3 and leave the hyphen for the caller. */
	check_option(test, "3-7", 3, 3, "-7");
	check_option(test, "0-1", 3, 0, "-1");
}

static void get_option_open_range(struct kunit *test)
{
	check_option(test, "3-", 3, 3, "-");
}

static void get_option_negative(struct kunit *test)
{
	check_option(test, "-5", 1, -5, "");
	check_option(test, "-1", 1, -1, "");
	check_option(test, "-0", 1, 0, "");
}

static void get_option_negative_with_comma(struct kunit *test)
{
	check_option(test, "-5,8", 2, -5, "8");
}

static void get_option_negative_range(struct kunit *test)
{
	check_option(test, "-3-5", 3, -3, "-5");
}

static void get_option_lone_hyphen(struct kunit *test)
{
	/*
	 * A hyphen with no digits after it is consumed, but no integer
	 * is reported.
	 */
	check_option(test, "-", 0, 0, "");
	check_option(test, "-x", 0, 0, "x");
}

static void get_option_hex_and_octal(struct kunit *test)
{
	check_option(test, "0x1f", 1, 31, "");
	check_option(test, "0x10,2", 2, 16, "2");
	check_option(test, "017", 1, 15, "");
	check_option(test, "010", 1, 8, "");
}

static void get_option_int_boundaries(struct kunit *test)
{
	check_option(test, "2147483647", 1, INT_MAX, "");
	check_option(test, "-2147483647", 1, -INT_MAX, "");
	check_option(test, "-2147483648", 1, INT_MIN, "");
	check_option(test, "2147483647,1", 2, INT_MAX, "1");
}

static void get_option_sequence(struct kunit *test)
{
	/* Walk a comma-separated list the way a caller would. */
	char *str = "1,2,3";
	int val;

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 2);
	KUNIT_EXPECT_EQ(test, val, 1);
	KUNIT_EXPECT_STREQ(test, str, "2,3");

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 2);
	KUNIT_EXPECT_EQ(test, val, 2);
	KUNIT_EXPECT_STREQ(test, str, "3");

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 1);
	KUNIT_EXPECT_EQ(test, val, 3);
	KUNIT_EXPECT_STREQ(test, str, "");

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 0);
}

static void get_option_range_caller_skips_hyphen(struct kunit *test)
{
	/* Parse "1-3,5" as a range followed by a value. */
	char *str = "1-3,5";
	int val;

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 3);
	KUNIT_EXPECT_EQ(test, val, 1);
	KUNIT_EXPECT_STREQ(test, str, "-3,5");

	str++;
	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 2);
	KUNIT_EXPECT_EQ(test, val, 3);
	KUNIT_EXPECT_STREQ(test, str, "5");
}

static void get_option_null_pint_validator(struct kunit *test)
{
	/* With a NULL @pint, the function only reports what it finds. */
	char *str = "42,7";

	KUNIT_EXPECT_EQ(test, get_option(&str, NULL), 2);
	KUNIT_EXPECT_STREQ(test, str, "7");

	str = "9";
	KUNIT_EXPECT_EQ(test, get_option(&str, NULL), 1);
	KUNIT_EXPECT_STREQ(test, str, "");

	str = "5-9";
	KUNIT_EXPECT_EQ(test, get_option(&str, NULL), 3);
	KUNIT_EXPECT_STREQ(test, str, "-9");

	str = "abc";
	KUNIT_EXPECT_EQ(test, get_option(&str, NULL), 0);
	KUNIT_EXPECT_STREQ(test, str, "abc");
}

static void get_option_start_offset(struct kunit *test)
{
	/* Parsing starts at *str, not at the beginning of the buffer. */
	char *str = "xx12,3" + 2;
	int val = SENTINEL;

	KUNIT_EXPECT_EQ(test, get_option(&str, &val), 2);
	KUNIT_EXPECT_EQ(test, val, 12);
	KUNIT_EXPECT_STREQ(test, str, "3");
}

