/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 */
#include <kunit/test.h>
#include <linux/string.h>

#define AGENT_SENTINEL	(-12345)
#define AGENT_BUF_LEN	16

/*
 * Call get_options() on @str with room for @nints entries and check:
 *  - the count stored in ints[0] equals @count,
 *  - ints[1..count] hold @want,
 *  - the returned pointer points at @tail,
 *  - nothing at or beyond ints[nints] was touched (no overflow).
 */
static void check_options(struct kunit *test, const char *str, int nints,
			  const int *want, int count, const char *tail)
{
	int buf[AGENT_BUF_LEN];
	char *ret;
	int i;

	for (i = 0; i < AGENT_BUF_LEN; i++)
		buf[i] = AGENT_SENTINEL;

	ret = get_options(str, nints, buf);

	KUNIT_EXPECT_EQ(test, buf[0], count);
	for (i = 0; i < count; i++)
		KUNIT_EXPECT_EQ(test, buf[i + 1], want[i]);
	KUNIT_EXPECT_STREQ(test, ret, tail);
	for (i = nints; i < AGENT_BUF_LEN; i++)
		KUNIT_EXPECT_EQ(test, buf[i], AGENT_SENTINEL);
}

/*
 * Validation mode (nints == 0): only ints[0] is written, with the count.
 */
static void check_validate(struct kunit *test, const char *str, int count,
			   const char *tail)
{
	int buf[2] = { AGENT_SENTINEL, AGENT_SENTINEL };
	char *ret;

	ret = get_options(str, 0, buf);

	KUNIT_EXPECT_EQ(test, buf[0], count);
	KUNIT_EXPECT_EQ(test, buf[1], AGENT_SENTINEL);
	KUNIT_EXPECT_STREQ(test, ret, tail);
}

/* Empty and non-numeric input */

static void agent_test_empty_string(struct kunit *test)
{
	check_options(test, "", 4, NULL, 0, "");
}

static void agent_test_non_numeric_start(struct kunit *test)
{
	check_options(test, "abc", 4, NULL, 0, "abc");
}

static void agent_test_leading_comma(struct kunit *test)
{
	check_options(test, ",1", 4, NULL, 0, ",1");
}

/* Single values */

static void agent_test_single_value(struct kunit *test)
{
	const int want[] = { 42 };

	check_options(test, "42", 4, want, 1, "");
}

static void agent_test_zero_value(struct kunit *test)
{
	const int want[] = { 0 };

	check_options(test, "0", 4, want, 1, "");
}

static void agent_test_negative_value(struct kunit *test)
{
	const int want[] = { -7 };

	check_options(test, "-7", 4, want, 1, "");
}

static void agent_test_hex_and_octal(struct kunit *test)
{
	const int want[] = { 16, 8 };

	check_options(test, "0x10,010", 4, want, 2, "");
}

/* Comma-separated lists */

static void agent_test_multiple_values(struct kunit *test)
{
	const int want[] = { 1, 2, 3 };

