/* Parse @str with memparse(), check the value and the returned end pointer. */
#define EXPECT_MEMPARSE(test, str, expected, consumed)				\
	do {									\
		const char *__s = (str);					\
		char *__end = NULL;						\
		unsigned long long __v = memparse(__s, &__end);			\
		KUNIT_EXPECT_EQ((test), __v, (unsigned long long)(expected));	\
		KUNIT_EXPECT_PTR_EQ((test), __end, (char *)__s + (consumed));	\
	} while (0)

static void memparse_plain_decimal(struct kunit *test)
{
	EXPECT_MEMPARSE(test, "0", 0, 1);
	EXPECT_MEMPARSE(test, "1", 1, 1);
	EXPECT_MEMPARSE(test, "9", 9, 1);
	EXPECT_MEMPARSE(test, "10", 10, 2);
	EXPECT_MEMPARSE(test, "42", 42, 2);
	EXPECT_MEMPARSE(test, "1023", 1023, 4);
	EXPECT_MEMPARSE(test, "1024", 1024, 4);
	EXPECT_MEMPARSE(test, "1000000", 1000000, 7);
}

static void memparse_stops_at_non_suffix(struct kunit *test)
{
	/* Unknown trailing characters are not consumed. */
	EXPECT_MEMPARSE(test, "123 rest", 123, 3);
	EXPECT_MEMPARSE(test, "7,8", 7, 1);
	EXPECT_MEMPARSE(test, "1B", 1, 1);
	EXPECT_MEMPARSE(test, "1 K", 1, 1);
	EXPECT_MEMPARSE(test, "5x", 5, 1);
	EXPECT_MEMPARSE(test, "5-6", 5, 1);
}

static void memparse_only_one_suffix_consumed(struct kunit *test)
{
	EXPECT_MEMPARSE(test, "1K", 1ULL << 10, 2);
	EXPECT_MEMPARSE(test, "1kB", 1ULL << 10, 2);
	EXPECT_MEMPARSE(test, "1KK", 1ULL << 10, 2);
	EXPECT_MEMPARSE(test, "1Mx", 1ULL << 20, 2);
}

static void memparse_suffix_k(struct kunit *test)
{
	EXPECT_MEMPARSE(test, "1K", 1ULL << 10, 2);
	EXPECT_MEMPARSE(test, "1k", 1ULL << 10, 2);
	EXPECT_MEMPARSE(test, "0K", 0, 2);
	EXPECT_MEMPARSE(test, "1023K", 1023ULL << 10, 5);
	EXPECT_MEMPARSE(test, "1023k", 1023ULL << 10, 5);
}

static void memparse_suffix_m(struct kunit *test)
{
	EXPECT_MEMPARSE(test, "1M", 1ULL << 20, 2);
	EXPECT_MEMPARSE(test, "1m", 1ULL << 20, 2);
	EXPECT_MEMPARSE(test, "1023M", 1023ULL << 20, 5);
	EXPECT_MEMPARSE(test, "1023m", 1023ULL << 20, 5);
}

static void memparse_suffix_g(struct kunit *test)
{
	EXPECT_MEMPARSE(test, "1G", 1ULL << 30, 2);
	EXPECT_MEMPARSE(test, "1g", 1ULL << 30, 2);
	EXPECT_MEMPARSE(test, "3G", 3ULL << 30, 2);
	EXPECT_MEMPARSE(test, "1023G", 1023ULL << 30, 5);
}

static void memparse_suffix_t(struct kunit *test)
{
	EXPECT_MEMPARSE(test, "1T", 1ULL << 40, 2);
	EXPECT_MEMPARSE(test, "1t", 1ULL << 40, 2);
	EXPECT_MEMPARSE(test, "1023T", 1023ULL << 40, 5);
}

static void memparse_suffix_p(struct kunit *test)
{
	EXPECT_MEMPARSE(test, "1P", 1ULL << 50, 2);
	EXPECT_MEMPARSE(test, "1p", 1ULL << 50, 2);
	EXPECT_MEMPARSE(test, "1023P", 1023ULL << 50, 5);
}

static void memparse_suffix_e(struct kunit *test)
{
	EXPECT_MEMPARSE(test, "1E", 1ULL << 60, 2);
	EXPECT_MEMPARSE(test, "1e", 1ULL << 60, 2);
	EXPECT_MEMPARSE(test, "15E", 15ULL << 60, 3);
}

static void memparse_suffix_exact_shift(struct kunit *test)
{
	/* Each suffix must be exactly 10 bits above the previous one. */
	EXPECT_MEMPARSE(test, "1023", 1023, 4);
	EXPECT_MEMPARSE(test, "1024", 1024, 4);
	EXPECT_MEMPARSE(test, "1K", 1024, 2);
	EXPECT_MEMPARSE(test, "1M", 1024 * 1024, 2);
	EXPECT_MEMPARSE(test, "1G", 1024ULL * 1024 * 1024, 2);
	EXPECT_MEMPARSE(test, "1T", 1024ULL * 1024 * 1024 * 1024, 2);
	EXPECT_MEMPARSE(test, "2G", 0x80000000ULL, 2);
	EXPECT_MEMPARSE(test, "4G", 0x100000000ULL, 2);
	EXPECT_MEMPARSE(test, "3K", 3072, 2);
}

static void memparse_suffix_bit_width(struct kunit *test)
{
	/* Results above 32 bits must not be truncated. */
	EXPECT_MEMPARSE(test, "4095M", 4095ULL << 20, 5);
	EXPECT_MEMPARSE(test, "5G", 5ULL << 30, 2);
	EXPECT_MEMPARSE(test, "8T", 8ULL << 40, 2);
	EXPECT_MEMPARSE(test, "1P", 1ULL << 50, 2);
}

static void memparse_max_representable_suffixed(struct kunit *test)
{
	/* 16383P is the largest P value that still fits in 64 bits. */
	EXPECT_MEMPARSE(test, "16383P", ~0ULL - ((1ULL << 50) - 1), 6);
	/* 15E is the largest E value that still fits in 64 bits. */
	EXPECT_MEMPARSE(test, "15E", 0xF000000000000000ULL, 3);
}

