/* Deterministic filler so any failure reproduces exactly. */
static u8 agent_pattern(u32 i)
{
	return (u8)((i * 2654435761u) >> 13);
}

static void agent_fill(u8 *buf, size_t n, u32 seed)
{
	size_t i;

	for (i = 0; i < n; i++)
		buf[i] = agent_pattern(i + seed);
}

/* Store the low @n bytes of @val in little-endian order. */
static void agent_put_le(u8 *dst, u64 val, size_t n)
{
	size_t i;

	for (i = 0; i < n; i++)
		dst[i] = (u8)(val >> (8 * i));
}

static u64 agent_rotl(u64 x, int b)
{
	return (x << b) | (x >> (64 - b));
}

static void agent_sipround(u64 *v)
{
	v[0] += v[1];
	v[1] = agent_rotl(v[1], 13);
	v[1] ^= v[0];
	v[0] = agent_rotl(v[0], 32);
	v[2] += v[3];
	v[3] = agent_rotl(v[3], 16);
	v[3] ^= v[2];
	v[0] += v[3];
	v[3] = agent_rotl(v[3], 21);
	v[3] ^= v[0];
	v[2] += v[1];
	v[1] = agent_rotl(v[1], 17);
	v[1] ^= v[2];
	v[2] = agent_rotl(v[2], 32);
}

/* Independent, byte-at-a-time SipHash-2-4 used as the oracle. */
static u64 agent_ref_siphash24(const u8 *in, size_t len,
			       const siphash_key_t *key)
{
	u64 v[4] = {
		key->key[0] ^ 0x736f6d6570736575ULL,
		key->key[1] ^ 0x646f72616e646f6dULL,
		key->key[0] ^ 0x6c7967656e657261ULL,
		key->key[1] ^ 0x7465646279746573ULL,
	};
	size_t full = len & ~(size_t)7;
	size_t i, j;
	u64 m, b;

	for (i = 0; i < full; i += 8) {
		m = 0;
		for (j = 0; j < 8; j++)
			m |= (u64)in[i + j] << (8 * j);
		v[3] ^= m;
		agent_sipround(v);
		agent_sipround(v);
		v[0] ^= m;
	}

	b = (u64)len << 56;
	for (j = 0; j < (len & 7); j++)
		b |= (u64)in[full + j] << (8 * j);
	v[3] ^= b;
	agent_sipround(v);
	agent_sipround(v);
	v[0] ^= b;
	v[2] ^= 0xff;
	for (j = 0; j < 4; j++)
		agent_sipround(v);

	return v[0] ^ v[1] ^ v[2] ^ v[3];
}

static void agent_vectors_test(struct kunit *test)
{
	u8 buf[64] __aligned(sizeof(u64));
	size_t len;

	agent_fill(buf, sizeof(buf), 0);
	for (len = 0; len < ARRAY_SIZE(agent_vectors); len++) {
		for (size_t i = 0; i < sizeof(buf); i++)
			buf[i] = (u8)i;
		KUNIT_EXPECT_EQ_MSG(test,
				    __siphash_aligned(buf, len, &agent_key),
				    agent_vectors[len],
				    "len=%zu", len);
	}
}

static void agent_reference_small_test(struct kunit *test)
{
	u8 buf[AGENT_MAX_LEN] __aligned(sizeof(u64));
	const siphash_key_t *keys[] = { &agent_key, &agent_other_key };
	size_t k, len;

	agent_fill(buf, sizeof(buf), 1);
	for (k = 0; k < ARRAY_SIZE(keys); k++) {
		for (len = 0; len <= 256; len++) {
			KUNIT_EXPECT_EQ_MSG(test,
					    __siphash_aligned(buf, len, keys[k]),
					    agent_ref_siphash24(buf, len, keys[k]),
					    "key=%zu len=%zu", k, len);
		}
	}
}

static void agent_reference_large_test(struct kunit *test)
{
	static const size_t lens[] = {
		255, 256, 257, 511, 512, 513, 1000, 1016, 1023,
	};
	u8 buf[AGENT_MAX_LEN] __aligned(sizeof(u64));
	size_t i;

	agent_fill(buf, sizeof(buf), 7);
	for (i = 0; i < ARRAY_SIZE(lens); i++) {
		KUNIT_EXPECT_EQ_MSG(test,
				    __siphash_aligned(buf, lens[i], &agent_key),
				    agent_ref_siphash24(buf, lens[i], &agent_key),
				    "len=%zu", lens[i]);
	}
}

/* Bytes at or past @len must not influence the result. This is what
 * the tail masking (or the byte switch) has to guarantee.
 */
static void agent_tail_ignored_test(struct kunit *test)
{
	u8 buf[256 + 16] __aligned(sizeof(u64));
	size_t len;
	u64 clean, dirty;

	for (len = 0; len <= 256; len++) {
		agent_fill(buf, sizeof(buf), 3);
		memset(buf + len, 0, sizeof(buf) - len);
		clean = __siphash_aligned(buf, len, &agent_key);

		memset(buf + len, 0xa5, sizeof(buf) - len);
		dirty = __siphash_aligned(buf, len, &agent_key);
		KUNIT_EXPECT_EQ_MSG(test, dirty, clean, "len=%zu", len);
	}
}

/* The length is mixed into the final block, so a message and the same
 * message with one extra trailing zero byte must hash differently.
 */
static void agent_length_mixed_test(struct kunit *test)
{
	u8 buf[257] __aligned(sizeof(u64));
	size_t len;

	memset(buf, 0, sizeof(buf));
	for (len = 0; len <= 256; len++) {
		KUNIT_EXPECT_NE_MSG(test,
				    __siphash_aligned(buf, len, &agent_key),
				    __siphash_aligned(buf, len + 1, &agent_key),
				    "len=%zu", len);
	}
}

/* Flipping any single byte of the input must change the hash. Catches
 * dropped bytes in the block loop or in the tail.
 */
static void agent_every_byte_test(struct kunit *test)
{
	u8 buf[64] __aligned(sizeof(u64));
	size_t len, j;
	u64 base;

	for (len = 1; len <= sizeof(buf); len++) {
		agent_fill(buf, len, 11);
		base = __siphash_aligned(buf, len, &agent_key);
		for (j = 0; j < len; j++) {
			buf[j] ^= 0x01;
			KUNIT_EXPECT_NE_MSG(test,
					    __siphash_aligned(buf, len, &agent_key),
					    base, "len=%zu byte=%zu", len, j);
			buf[j] ^= 0x01;
		}
	}
}

/* Both key halves must feed into the result for every length. */
static void agent_key_test(struct kunit *test)
{
	siphash_key_t key0 = agent_key;
	siphash_key_t key1 = agent_key;
	u8 buf[256] __aligned(sizeof(u64));
	size_t len;

	key0.key[0] ^= 1;
	key1.key[1] ^= 1;
	agent_fill(buf, sizeof(buf), 5);
	for (len = 0; len <= 256; len++) {
		u64 base = __siphash_aligned(buf, len, &agent_key);

		KUNIT_EXPECT_NE_MSG(test,
				    __siphash_aligned(buf, len, &agent_other_key),
				    base, "len=%zu", len);
		KUNIT_EXPECT_NE_MSG(test,
				    __siphash_aligned(buf, len, &key0),
				    base, "len=%zu key0", len);
		KUNIT_EXPECT_NE_MSG(test,
				    __siphash_aligned(buf, len, &key1),
				    base, "len=%zu key1", len);
	}
}

/* The fixed-width helpers have their own code paths and must agree
 * with the generic function on the same little-endian bytes.
 */
static void agent_fixed_width_test(struct kunit *test)
{
	u8 buf[32] __aligned(sizeof(u64));
	const u32 a32 = 0x03020100U, b32 = 0x07060504U;
	const u32 c32 = 0x0b0a0908U, d32 = 0x0f0e0d0cU;
	const u64 a64 = 0x0706050403020100ULL, b64 = 0x0f0e0d0c0b0a0908ULL;
	const u64 c64 = 0x1716151413121110ULL, d64 = 0x1f1e1d1c1b1a1918ULL;

	agent_put_le(buf, a32, 4);
	KUNIT_EXPECT_EQ(test, __siphash_aligned(buf, 4, &agent_key),
			siphash_1u32(a32, &agent_key));

	agent_put_le(buf, a32, 4);
	agent_put_le(buf + 4, b32, 4);
	KUNIT_EXPECT_EQ(test, __siphash_aligned(buf, 8, &agent_key),
			siphash_2u32(a32, b32, &agent_key));

	agent_put_le(buf + 8, c32, 4);
	KUNIT_EXPECT_EQ(test, __siphash_aligned(buf, 12, &agent_key),
			siphash_3u32(a32, b32, c32, &agent_key));

	agent_put_le(buf + 12, d32, 4);
	KUNIT_EXPECT_EQ(test, __siphash_aligned(buf, 16, &agent_key),
			siphash_4u32(a32, b32, c32, d32, &agent_key));

	agent_put_le(buf, a64, 8);
	KUNIT_EXPECT_EQ(test, __siphash_aligned(buf, 8, &agent_key),
			siphash_1u64(a64, &agent_key));

	agent_put_le(buf + 8, b64, 8);
	KUNIT_EXPECT_EQ(test, __siphash_aligned(buf, 16, &agent_key),
			siphash_2u64(a64, b64, &agent_key));

	agent_put_le(buf + 16, c64, 8);
	KUNIT_EXPECT_EQ(test, __siphash_aligned(buf, 24, &agent_key),
			siphash_3u64(a64, b64, c64, &agent_key));

	agent_put_le(buf + 24, d64, 8);
	KUNIT_EXPECT_EQ(test, __siphash_aligned(buf, 32, &agent_key),
			siphash_4u64(a64, b64, c64, d64, &agent_key));
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_vectors_test),
	KUNIT_CASE(agent_reference_small_test),
	KUNIT_CASE(agent_reference_large_test),
	KUNIT_CASE(agent_tail_ignored_test),
	KUNIT_CASE(agent_length_mixed_test),
	KUNIT_CASE(agent_every_byte_test),
	KUNIT_CASE(agent_key_test),
	KUNIT_CASE(agent_fixed_width_test),
	{}
};

static struct kunit_suite agent_test_suite = {
